function pairs(items){
  // items: [{id, group}]; return distinct unordered pairs sharing a group
  const out = [];
  for (const a of items){
    for (const b of items){
      if (a.group === b.group){
        out.push([a.id, b.id]);
      }
    }
  }
  return out;
}
this.pairs = pairs;

tasks.verify:
const items=[{id:1,group:'g'},{id:2,group:'g'},{id:3,group:'g'},{id:4,group:'h'}];
const out=pairs(items);
const keys=out.map(p=>p[0]+'-'+p[1]).sort().join('|');
const noSelf = out.every(p=>p[0]!==p[1]);
const canon = out.every(p=>p[0]<p[1]);
const ok = out.length===3 && noSelf && canon && keys==='1-2|1-3|2-3';
console.log(ok ? 'PASS' : 'FAIL len='+out.length+' keys='+keys);
